	}

	/* @Override */
	public List<Symbol> getSymbols(string name, Namespace @namespace) {
		TraceNamespaceSymbol parent = assertTraceNamespace(@namespace);
		using (LockHold hold = program.trace.lockRead())
{
			List<Symbol> result = new();
			foreach (TraceSymbol sym in symbolManager.allSymbols().getChildrenNamed(name, parent)) {
				if (requireVisible(sym) != null) {
					result.add(sym);
				}
			}
			return result;
		}
	}

